mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM property
    WHERE id = #{propertyId}
)

SELECT p.id AS property_id, b.latitude AS building_latitude, b.longitude AS building_longitude, s.id AS safe_id, s.safe_category AS safe_category, s.count_within500m AS count_within500m, s.nearest_distance_meters AS nearest_distance_meters, ( SELECT sd_near.safe_name FROM safety_detail sd_near WHERE sd_near.safe_id = s.id ORDER BY sd_near.sort_order ASC LIMIT 1 ) AS nearest_safe_name, sd.id AS detail_id, sd.safe_name AS detail_safe_name, sd.latitude AS detail_latitude, sd.longitude AS detail_longitude, sd.distance_m AS detail_distance_m, sd.polygon AS detail_polygon, 1 AS query_order FROM property p INNER JOIN building b ON p.building_id = b.id INNER JOIN safety s ON b.id = s.building_id AND s.safe_category != 'POLICE_CENTER' LEFT JOIN safety_detail sd ON s.id = sd.safe_id WHERE p.id = #{propertyId}
UNION ALL
SELECT p.id AS property_id, b.latitude AS building_latitude, b.longitude AS building_longitude, (i.id + 900000) AS safe_id, 'POLICE_CENTER' AS safe_category, i.count_within2000m AS count_within500m, i.nearest_distance_meters AS nearest_distance_meters, ( SELECT id_near.infra_name FROM infrastructure_detail id_near WHERE id_near.infra_id = i.id ORDER BY id_near.sort_order ASC LIMIT 1 ) AS nearest_safe_name, id.id AS detail_id, id.infra_name AS detail_safe_name, id.latitude AS detail_latitude, id.longitude AS detail_longitude, id.distance_m AS detail_distance_m, NULL AS detail_polygon, 2 AS query_order FROM property p INNER JOIN building b ON p.building_id = b.id INNER JOIN infrastructure i ON b.id = i.building_id AND i.infra_category = 'POLICE' LEFT JOIN infrastructure_detail id ON i.id = id.infra_id WHERE p.id = #{propertyId}
ORDER BY safe_id ASC
